import snapshotRows from './real-data-snapshot.json';

export type SnapshotRecommendationRow = {
  'shop id': string;
  申样时间: string;
  产品id: string;
  达人handle: string;
  类型: '必寄' | '应寄';
};
export type Recommendation = {
  shopId: string;
  requestDate: string;
  productId: string;
  creator: string;
  type: '必寄' | '应寄';
};

export const SNAPSHOT_RECOMMENDATIONS =
  snapshotRows as SnapshotRecommendationRow[];

export function filterRecommendations(shopId: string): Recommendation[] {
  const target = shopId.trim();
  return SNAPSHOT_RECOMMENDATIONS.filter(
    row => String(row['shop id']).trim() === target,
  )
    .map(row => ({
      shopId: String(row['shop id']).trim(),
      requestDate: row.申样时间,
      productId: String(row.产品id),
      creator: row.达人handle,
      type: row.类型,
    }))
    .sort((a, b) => Number(b.type === '必寄') - Number(a.type === '必寄'));
}

export function buildCsv(rows: Recommendation[]): string {
  const headers = [
    '优先级/类型',
    '达人 handle',
    '商品 ID',
    '申样时间',
    'Shop ID',
  ];
  const quoteCsvCell = (value: string) => `"${value.replace(/"/g, '""')}"`;
  return [
    headers,
    ...rows.map(row => [
      row.type,
      row.creator,
      row.productId,
      row.requestDate,
      row.shopId,
    ]),
  ]
    .map(row => row.map(quoteCsvCell).join(','))
    .join('\r\n');
}

export function exportCsv(rows: Recommendation[], shopId: string) {
  const blob = new Blob([`\uFEFF${buildCsv(rows)}`], {
    type: 'text/csv;charset=utf-8',
  });
  const link = document.createElement('a');
  link.href = URL.createObjectURL(blob);
  link.download = `TikTok-Shop-寄样推荐_${shopId}_${new Date().toISOString().slice(0, 10)}.csv`;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(link.href);
}
